import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_layer_norm_kernel(
    float const* x,
    float const* weight,
    float const* bias,
    float* y,
    int64_t rows,
    int64_t cols,
    float eps)
{
    int64_t row = static_cast<int64_t>(blockIdx.x);
    int tid = threadIdx.x;

    if (row >= rows) {
        return;
    }

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(rows, cols),
        make_stride(cols, Int<1>{}));

    auto gY = make_tensor(
        make_gmem_ptr(y),
        make_shape(rows, cols),
        make_stride(cols, Int<1>{}));

    auto gW = make_tensor(
        make_gmem_ptr(weight),
        make_shape(cols),
        make_stride(Int<1>{}));

    auto gB = make_tensor(
        make_gmem_ptr(bias),
        make_shape(cols),
        make_stride(Int<1>{}));

    __shared__ float reduction[256];

    float sum = 0.0f;
    for (int64_t col = tid; col < cols; col += blockDim.x) {
        sum += gX(row, col);
    }

    reduction[tid] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            reduction[tid] += reduction[tid + stride];
        }
        __syncthreads();
    }

    float mean = reduction[0] / static_cast<float>(cols);

    float variance_sum = 0.0f;
    for (int64_t col = tid; col < cols; col += blockDim.x) {
        float diff = gX(row, col) - mean;
        variance_sum += diff * diff;
    }

    reduction[tid] = variance_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            reduction[tid] += reduction[tid + stride];
        }
        __syncthreads();
    }

    float variance = reduction[0] / static_cast<float>(cols);
    float inv_std = rsqrtf(variance + eps);

    for (int64_t col = tid; col < cols; col += blockDim.x) {
        float normalized = (gX(row, col) - mean) * inv_std;
        gY(row, col) = normalized * gW(col) + gB(col);
    }
}


torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(),
                "weight and bias must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat,
                "x must have dtype float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat &&
                bias.scalar_type() == at::kFloat,
                "weight and bias must have dtype float32");
    TORCH_CHECK(x.dim() >= 3, "x must have at least three dimensions");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous() && bias.is_contiguous(),
                "weight and bias must be contiguous");

    int64_t cols = x.size(x.dim() - 3) *
                   x.size(x.dim() - 2) *
                   x.size(x.dim() - 1);

    int64_t rows = x.numel() / cols;

    TORCH_CHECK(weight.numel() == cols,
                "weight must contain one value per normalized element");
    TORCH_CHECK(bias.numel() == cols,
                "bias must contain one value per normalized element");

    auto y = torch::empty_like(x);

    dim3 block(256);
    dim3 grid(static_cast<unsigned int>(rows));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_layer_norm_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        y.data_ptr<float>(),
        rows,
        cols,
        static_cast<float>(eps));

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE layer normalization kernel launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_layer_norm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layer_norm"],
    extra_cflags=[
        "-O3",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()

        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layer_norm(
            x,
            self.weight,
            self.bias,
            self.eps,
        )

